import{$ as e,Ft as t,bt as n,gt as r,jt as i,pt as a,vt as o,yt as s}from"./chunks/framework.CbVAkGq1.js";import"./chunks/assets.qpmlsi8y.js";var c=JSON.parse(`{"title":"第四章：管制药物化学结构图谱全典 (Chemical Structures of Scheduled Drugs)","description":"","frontmatter":{},"headers":[],"relativePath":"controlled-substances/chapter-4.md","filePath":"zh/controlled-substances/chapter-4.md"}`),l={name:`controlled-substances/chapter-4.md`};function u(e,c,l,u,d,f){let p=t(`NolebasePageProperties`),m=t(`NolebaseGitContributors`),h=t(`NolebaseGitChangelog`);return i(),r(`div`,null,[c[0]||=a(`h1`,{id:`第四章-管制药物化学结构图谱全典-chemical-structures-of-scheduled-drugs`,tabindex:`-1`},[s(`第四章：管制药物化学结构图谱全典 (Chemical Structures of Scheduled Drugs) `),a(`a`,{class:`header-anchor`,href:`#第四章-管制药物化学结构图谱全典-chemical-structures-of-scheduled-drugs`,"aria-label":`Permalink to “第四章：管制药物化学结构图谱全典 (Chemical Structures of Scheduled Drugs)”`},`​`),s(),a(`a`,{class:`header-anchor`,href:`#第四章-管制药物化学结构图谱全典-chemical-structures-of-scheduled-drugs`,"aria-label":`Permalink to “第四章：管制药物化学结构图谱全典 (Chemical Structures of Scheduled Drugs)”`},`​`)],-1),n(p),c[1]||=o(`<blockquote><p><strong>著者</strong>：Alexander T. Shulgin, Ph.D.<br><strong>出处</strong>：<em>Controlled Substances: A Chemical and Legal Guide to the Federal Drug Laws (2nd Edition, 1992)</em>, Chapter 4, pp. 267–302.<br><strong>学术规范</strong>：本章忠实于原书第 253–288 页的有机化学分类与原图谱系，将原书全部 33 组化学分子谱系图完整嵌入，并对舒尔金博士撰写的所有结构变迁、类似物法案映射、构效关系分析进行逐字逐段精译。</p></blockquote><hr><h2 id="章节引言-化学家的视角与类似物法案困境" tabindex="-1">章节引言：化学家的视角与类似物法案困境 <a class="header-anchor" href="#章节引言-化学家的视角与类似物法案困境" aria-label="Permalink to “章节引言：化学家的视角与类似物法案困境”">​</a> <a class="header-anchor" href="#章节引言-化学家的视角与类似物法案困境" aria-label="Permalink to “章节引言：化学家的视角与类似物法案困境”">​</a></h2><p>在本参考手册的其他章节中，依据《受管制物质法》被列管的药物主要按两种方式进行组织编排：</p><ul><li>在第二章中，它们按照名称及各学科同义词的英文字母顺序进行罗列；</li><li>在第五章中，它们按照美国缉毒署（DEA）为其分配的任意四位代码编号的数值大小进行排列。</li></ul><p><strong>而本章则是专门为了唤起化学家的研究志趣而设计的。</strong></p><p>在这一章节中，全部受管制药物集合完全依据<strong>分子结构的内在逻辑（structural logic）</strong>进行系统的分类和展开。对于关注毒品管制法律前沿的科研人员而言，这种结构化的全景呈现具有多重不可估量的核心学术价值：</p><h3 id="_1-应对-1986-年《受管制物质类似物法案》的实质相似性判定" tabindex="-1">1. 应对 1986 年《受管制物质类似物法案》的实质相似性判定 <a class="header-anchor" href="#_1-应对-1986-年《受管制物质类似物法案》的实质相似性判定" aria-label="Permalink to “1. 应对 1986 年《受管制物质类似物法案》的实质相似性判定”">​</a> <a class="header-anchor" href="#_1-应对-1986-年《受管制物质类似物法案》的实质相似性判定" aria-label="Permalink to “1. 应对 1986 年《受管制物质类似物法案》的实质相似性判定”">​</a></h3><p>随着《类似物法案》的颁布生效，司法指控的重心被前所未有地转移到了一种全新合成化学品与已被某一附表列管的基准物质之间<strong>“分子结构的相似性”</strong>（或其预期的药理作用相似性）之上。</p><p>本章完全基于结构骨架的内在同源性进行构建。试以<strong>吗啡类类似物（Morphine analogs）</strong>这一化学族群为例： 在由母体四环系统（环菲骨架与含氮杂环）构成的严格取代产物类别中，成文法明文列出并分配了专属代码的管制药物便有 16 种之多。虽然其中只有极少数药物能够在美国凭合法医疗处方获得，但现代药理学教科书中收录了更多的衍生品种，只要随手翻阅一下《化学文摘》（Chemical Abstracts），便会赫然发现成百上千种在分子结构上存在亲缘关系的同系物。</p><p>在过去传统的列管诉讼辩论中，政府控方必须提供确凿证据论证该物质具有“滥用潜能”；然而在全新的类似物法律框架下，<strong>仅仅证明分子结构的相似性，便足以使持有该化学品直接构成联邦重罪</strong>！诚然，成文法要求控方证明其持有“旨在供人类摄入”，但众所周知，探索人类药效本就是全美乃至全球每一家正规制药企业中每一位药物化学家进行药物创新的终极目标。科研人员必须保持清醒认知：科学界永远不乏就两种不同分子结构之间是“相似”还是“不相似”各抒己见的权威专家，而在未来的法庭审判中，控辩双方永远都会在诉讼中迫切争夺这两类截然相反的专家证词。</p><h3 id="_2-法律灰色地带与-衍生物-的无限扩张陷阱" tabindex="-1">2. 法律灰色地带与“衍生物”的无限扩张陷阱 <a class="header-anchor" href="#_2-法律灰色地带与-衍生物-的无限扩张陷阱" aria-label="Permalink to “2. 法律灰色地带与“衍生物”的无限扩张陷阱”">​</a> <a class="header-anchor" href="#_2-法律灰色地带与-衍生物-的无限扩张陷阱" aria-label="Permalink to “2. 法律灰色地带与“衍生物”的无限扩张陷阱”">​</a></h3><p>现行《受管制物质法》的一个巨大法律灰色地带，在于药物附表正式名录前的序言中充斥着大量的<strong>概括性兜底条款</strong>。这些条款往往诉诸极其模糊的术语，且在司法实践中绝大多数从未在最高法院经历过违宪审查考验。</p><p>这种立法草率最典型的例证，莫过于附表二在正式列举天然鸦片生物碱之前的那段序言：法条规定，除明确列出的极少数例外之外，<strong>“鸦片的任何衍生物”（any derivative of Opium）均应无条件视为附表二管制药物</strong>。从最宽泛的法理字面推导，这意味着只要任何人能够以鸦片中的任何成分（例如吗啡）为原料合成制备出任何化学衍生物（哪怕只是极其平庸的正丁基季铵盐），该产物即使此前在人类科学史上从未被合成过、且没有任何人证实其存在任何滥用潜能，它自诞生那一秒起就已经是联邦重罪管辖下的附表二法定毒品！</p><p>这一极端法理假设在司法行政先例中得到了确凿印证——最雄辩的例证就是<strong>阿扑吗啡（Apomorphine）</strong>与<strong>纳曲酮（Naltrexone）</strong>的立法地位。它们作为附表二未列名隐性成员的法律地位，恰恰是在司法部事后专门下达行政命令通过指名道姓将其从管制附表中“除名与去管制化”时，才在法律层面上被反向证实的！既然它们此前必须通过特别指名豁免才能合法存在，那就意味着全美法律界必须默认接受一个荒谬的前提：<strong>凡是能够从鸦片生物碱中衍生出的所有未知化学分子，早已全部被该“衍生物”兜底网罗在附表二的黑名单之中</strong>。</p><hr><h2 id="_33-类受管制药物化学结构图谱全览" tabindex="-1">33 类受管制药物化学结构图谱全览 <a class="header-anchor" href="#_33-类受管制药物化学结构图谱全览" aria-label="Permalink to “33 类受管制药物化学结构图谱全览”">​</a> <a class="header-anchor" href="#_33-类受管制药物化学结构图谱全览" aria-label="Permalink to “33 类受管制药物化学结构图谱全览”">​</a></h2><p>以下为全书第四章收录的全部 33 组化学分子谱系图，精确对齐原书扫描底本与矢量化学绘制：</p><h3 id="_1-阿片类药物分子演进史与骨架裂解递变" tabindex="-1">1. 阿片类药物分子演进史与骨架裂解递变 <a class="header-anchor" href="#_1-阿片类药物分子演进史与骨架裂解递变" aria-label="Permalink to “1. 阿片类药物分子演进史与骨架裂解递变”">​</a> <a class="header-anchor" href="#_1-阿片类药物分子演进史与骨架裂解递变" aria-label="Permalink to “1. 阿片类药物分子演进史与骨架裂解递变”">​</a></h3><p><img src="/images/controlled-substances/01-opiate-progression.png" alt="阿片类药物分子演进史" width="1231" height="1677"></p><ul><li><strong>化学骨架解析</strong>：从天然五环吗啡烷体系（Morphine，环 A/B/C/D/E 完整）逐步拆解： <ul><li>切断环 4,5-环氧桥（Ring 4,5-ether bridge）演进为四环体系<strong>吗啡喃类（Morphinans，如左啡诺 Levorphanol）</strong>；</li><li>进一步切断 C 环演进为三环体系<strong>苯并吗喃类（Benzomorphans，如喷他佐新 Pentazocine）</strong>；</li><li>进一步切断 B 环演进为双环体系<strong>苯基哌啶类（Phenylpiperidines，如哌替啶 Meperidine/杜冷丁）</strong>；</li><li>最终彻底裂解杂环演进为开链单环体系<strong>美沙酮类（Methadones）</strong>。</li></ul></li></ul><h3 id="_2-苯基哌啶与芬太尼类结构谱系" tabindex="-1">2. 苯基哌啶与芬太尼类结构谱系 <a class="header-anchor" href="#_2-苯基哌啶与芬太尼类结构谱系" aria-label="Permalink to “2. 苯基哌啶与芬太尼类结构谱系”">​</a> <a class="header-anchor" href="#_2-苯基哌啶与芬太尼类结构谱系" aria-label="Permalink to “2. 苯基哌啶与芬太尼类结构谱系”">​</a></h3><p><img src="/images/controlled-substances/02-phenylpiperidines-fentanyl.png" alt="苯基哌啶与芬太尼类结构谱系" width="1281" height="1661"></p><ul><li><strong>代表性化合物</strong>：芬太尼母体（Fentanyl）、阿芬太尼（Alfentanil）、舒芬太尼（Sufentanil）、卡芬太尼（Carfentanil）、α-甲基芬太尼（Alpha-methylfentanyl，著名的街头类似物“中国白”）。</li></ul><h3 id="_3-中枢药理分类总览-第一部分-麻醉、致幻与兴奋剂" tabindex="-1">3. 中枢药理分类总览（第一部分：麻醉、致幻与兴奋剂） <a class="header-anchor" href="#_3-中枢药理分类总览-第一部分-麻醉、致幻与兴奋剂" aria-label="Permalink to “3. 中枢药理分类总览（第一部分：麻醉、致幻与兴奋剂）”">​</a> <a class="header-anchor" href="#_3-中枢药理分类总览-第一部分-麻醉、致幻与兴奋剂" aria-label="Permalink to “3. 中枢药理分类总览（第一部分：麻醉、致幻与兴奋剂）”">​</a></h3><p><img src="/images/controlled-substances/03-pharmacological-groups-overview-1.png" alt="中枢药理分类总览图 1" width="1231" height="1677"></p><ul><li><strong>涵盖大类</strong>：强效阿片镇痛剂、吲哚生物碱致幻剂（麦角酸二乙酰胺 LSD、裸盖菇素 Psilocybin、二甲基色胺 DMT）、苯乙胺类兴奋剂与致幻剂（安非他命、甲基苯丙胺、甲氧基苯丙胺 PMA、DOM/STP）。</li></ul><h3 id="_4-中枢药理分类总览-第二部分-抑制剂与镇静催眠药" tabindex="-1">4. 中枢药理分类总览（第二部分：抑制剂与镇静催眠药） <a class="header-anchor" href="#_4-中枢药理分类总览-第二部分-抑制剂与镇静催眠药" aria-label="Permalink to “4. 中枢药理分类总览（第二部分：抑制剂与镇静催眠药）”">​</a> <a class="header-anchor" href="#_4-中枢药理分类总览-第二部分-抑制剂与镇静催眠药" aria-label="Permalink to “4. 中枢药理分类总览（第二部分：抑制剂与镇静催眠药）”">​</a></h3><p><img src="/images/controlled-substances/04-pharmacological-groups-overview-2.png" alt="中枢药理分类总览图 2" width="1279" height="1661"></p><ul><li><strong>涵盖大类</strong>：经典巴比妥酸类衍生物（长效、中效、超短效巴比妥）、1,4-苯二氮䓬类中枢神经抑制剂、喹唑酮类（安眠酮/甲喹酮 Methaqualone）、氨基甲酸酯类镇静药（眠尔通/甲丙氨酯 Meprobamate）。</li></ul><h3 id="_5-吗啡经典母核环系与取代模式" tabindex="-1">5. 吗啡经典母核环系与取代模式 <a class="header-anchor" href="#_5-吗啡经典母核环系与取代模式" aria-label="Permalink to “5. 吗啡经典母核环系与取代模式”">​</a> <a class="header-anchor" href="#_5-吗啡经典母核环系与取代模式" aria-label="Permalink to “5. 吗啡经典母核环系与取代模式”">​</a></h3><p><img src="/images/controlled-substances/05-morphine-ring-skeleton.png" alt="吗啡经典母核环系" width="1232" height="1677"></p><ul><li><strong>结构解析</strong>：展示环 A（苯环 3 位酚羟基）、环 C（6 位醇羟基与 7,8 位双键）、环 D（含氮哌啶杂环与 N-17 甲基取代）。3 位酚羟基的甲基化生成<strong>可待因（Codeine）</strong>，乙酰化生成<strong>海洛因（Heroin/3,6-二乙酰吗啡）</strong>。</li></ul><h3 id="_6-二氢吗啡酮与二氢可待因酮骨架" tabindex="-1">6. 二氢吗啡酮与二氢可待因酮骨架 <a class="header-anchor" href="#_6-二氢吗啡酮与二氢可待因酮骨架" aria-label="Permalink to “6. 二氢吗啡酮与二氢可待因酮骨架”">​</a> <a class="header-anchor" href="#_6-二氢吗啡酮与二氢可待因酮骨架" aria-label="Permalink to “6. 二氢吗啡酮与二氢可待因酮骨架”">​</a></h3><p><img src="/images/controlled-substances/06-dihydromorphine-skeleton.png" alt="二氢吗啡骨架衍生物" width="1283" height="1654"></p><ul><li><strong>结构解析</strong>：环 C 的 7,8 位双键氢化饱和，且 6 位羟基氧化为酮基。涵盖<strong>氢吗啡酮（Hydromorphone）</strong>、<strong>氢可酮（Hydrocodone）</strong>及其 14-羟基化衍生物<strong>羟考酮（Oxycodone）</strong>与<strong>羟吗啡酮（Oxymorphone）</strong>。</li></ul><h3 id="_7-复杂吗啡变体与天然阿片伴生生物碱" tabindex="-1">7. 复杂吗啡变体与天然阿片伴生生物碱 <a class="header-anchor" href="#_7-复杂吗啡变体与天然阿片伴生生物碱" aria-label="Permalink to “7. 复杂吗啡变体与天然阿片伴生生物碱”">​</a> <a class="header-anchor" href="#_7-复杂吗啡变体与天然阿片伴生生物碱" aria-label="Permalink to “7. 复杂吗啡变体与天然阿片伴生生物碱”">​</a></h3><p><img src="/images/controlled-substances/07-other-morphine-derivatives.png" alt="其他吗啡类衍生物" width="1231" height="1679"></p><ul><li><strong>涵盖分子</strong>：蒂巴因（Thebaine，6,8-二烯醚）、乙基吗啡（Ethylmorphine/狄奥宁）、苄吗啡（Benzylmorphine）、尼可吗啡（Nicomorphine，双烟酸酯）以及阿扑吗啡（Apomorphine）。</li></ul><h3 id="_8-狄尔斯-阿尔德-diels-alder-桥环奥利帕文与埃托啡衍生物" tabindex="-1">8. 狄尔斯-阿尔德（Diels-Alder）桥环奥利帕文与埃托啡衍生物 <a class="header-anchor" href="#_8-狄尔斯-阿尔德-diels-alder-桥环奥利帕文与埃托啡衍生物" aria-label="Permalink to “8. 狄尔斯-阿尔德（Diels-Alder）桥环奥利帕文与埃托啡衍生物”">​</a> <a class="header-anchor" href="#_8-狄尔斯-阿尔德-diels-alder-桥环奥利帕文与埃托啡衍生物" aria-label="Permalink to “8. 狄尔斯-阿尔德（Diels-Alder）桥环奥利帕文与埃托啡衍生物”">​</a></h3><p><img src="/images/controlled-substances/08-diels-alder-oripavine.png" alt="狄尔斯-阿尔德加成物与奥利帕文" width="1283" height="1650"></p><ul><li><strong>涵盖分子</strong>：由蒂巴因与亲双烯体经 Diels-Alder 环加成反应制得的强效 6,14-桥亚乙基四氢奥利帕文系列，包括人类药力极强的大型动物镇静剂<strong>埃托啡（Etorphine，镇痛强度为吗啡的 1,000–8,000 倍）</strong>及其解毒拮抗剂<strong>地普诺啡（Diprenorphine）</strong>与<strong>丁丙诺啡（Buprenorphine）</strong>。</li></ul><h3 id="_9-吗啡喃-morphinans-与苯并吗喃-benzomorphans" tabindex="-1">9. 吗啡喃（Morphinans）与苯并吗喃（Benzomorphans） <a class="header-anchor" href="#_9-吗啡喃-morphinans-与苯并吗喃-benzomorphans" aria-label="Permalink to “9. 吗啡喃（Morphinans）与苯并吗喃（Benzomorphans）”">​</a> <a class="header-anchor" href="#_9-吗啡喃-morphinans-与苯并吗喃-benzomorphans" aria-label="Permalink to “9. 吗啡喃（Morphinans）与苯并吗喃（Benzomorphans）”">​</a></h3><p><img src="/images/controlled-substances/09-morphinan-and-benzomorphan.png" alt="吗啡喃与苯并吗喃" width="1231" height="1679"></p><ul><li><strong>结构解析</strong>：剥离 4,5-醚桥。左旋体<strong>左啡诺（Levorphanol）</strong>为强效阿片镇痛剂（列入附表二）；而其右旋对映异构体<strong>右美沙芬（Dextromethorphan）</strong>则丧失阿片受体镇痛活性，转化为中枢镇咳药，成文法明文将其特别排除于管制品之外。</li></ul><h3 id="_10-4-苯基哌啶-4-羧酸乙酯类-哌替啶同系物" tabindex="-1">10. 4-苯基哌啶-4-羧酸乙酯类（哌替啶同系物） <a class="header-anchor" href="#_10-4-苯基哌啶-4-羧酸乙酯类-哌替啶同系物" aria-label="Permalink to “10. 4-苯基哌啶-4-羧酸乙酯类（哌替啶同系物）”">​</a> <a class="header-anchor" href="#_10-4-苯基哌啶-4-羧酸乙酯类-哌替啶同系物" aria-label="Permalink to “10. 4-苯基哌啶-4-羧酸乙酯类（哌替啶同系物）”">​</a></h3><p><img src="/images/controlled-substances/10-ethyl-4-piperidinecarboxylate.png" alt="4-哌啶羧酸乙酯衍生物" width="1274" height="1659"></p><ul><li><strong>涵盖分子</strong>：<strong>哌替啶（Meperidine / 杜冷丁）</strong>、阿尼利啶（Anileridine）、地芬诺酯（Diphenoxylate）。</li></ul><h3 id="_11-4-苯基-4-丙酰氧基哌啶类-prodine-系列" tabindex="-1">11. 4-苯基-4-丙酰氧基哌啶类（Prodine 系列） <a class="header-anchor" href="#_11-4-苯基-4-丙酰氧基哌啶类-prodine-系列" aria-label="Permalink to “11. 4-苯基-4-丙酰氧基哌啶类（Prodine 系列）”">​</a> <a class="header-anchor" href="#_11-4-苯基-4-丙酰氧基哌啶类-prodine-系列" aria-label="Permalink to “11. 4-苯基-4-丙酰氧基哌啶类（Prodine 系列）”">​</a></h3><p><img src="/images/controlled-substances/11-4-propionyloxy-piperidines.png" alt="4-丙酰氧基哌啶类" width="1231" height="1679"></p><ul><li><strong>涵盖分子</strong>：α-普罗丁（Alphaprodine）、β-普罗丁（Betaprodine）、烯丙普罗丁（Allylprodine）、以及历史上著名的致帕金森氏症神经毒素前体杂质 <strong>MPPP 与 MPTP</strong>。</li></ul><h3 id="_12-芬太尼母核-4-苯胺基哌啶衍生物" tabindex="-1">12. 芬太尼母核（4-苯胺基哌啶衍生物） <a class="header-anchor" href="#_12-芬太尼母核-4-苯胺基哌啶衍生物" aria-label="Permalink to “12. 芬太尼母核（4-苯胺基哌啶衍生物）”">​</a> <a class="header-anchor" href="#_12-芬太尼母核-4-苯胺基哌啶衍生物" aria-label="Permalink to “12. 芬太尼母核（4-苯胺基哌啶衍生物）”">​</a></h3><p><img src="/images/controlled-substances/12-fentanyl-skeleton.png" alt="芬太尼基础母核骨架" width="1277" height="1654"></p><ul><li><strong>结构解析</strong>：展示 N-苯基-N-(4-哌啶基)丙酰胺的核心分子拓扑学，剖析哌啶环 1 位苯乙基侧链与 4 位酰苯胺基团的药效团几何构象。</li></ul><h3 id="_13-芬太尼高级类似物谱系" tabindex="-1">13. 芬太尼高级类似物谱系 <a class="header-anchor" href="#_13-芬太尼高级类似物谱系" aria-label="Permalink to “13. 芬太尼高级类似物谱系”">​</a> <a class="header-anchor" href="#_13-芬太尼高级类似物谱系" aria-label="Permalink to “13. 芬太尼高级类似物谱系”">​</a></h3><p><img src="/images/controlled-substances/13-fentanyl-analogues.png" alt="芬太尼衍生物与类似物谱系" width="1234" height="1675"></p><ul><li><strong>涵盖分子</strong>：<strong>α-甲基芬太尼（Alpha-methylfentanyl）</strong>、<strong>3-甲基芬太尼（3-Methylfentanyl）</strong>（活性高达吗啡千倍）、对氟芬太尼（Para-fluorofentanyl）、硫代芬太尼（Thiofentanyl）等 1980 年代地下黑市设计毒品核心名录。</li></ul><h3 id="_14-美沙酮-methadone-开链二苯烷基胺母核" tabindex="-1">14. 美沙酮（Methadone）开链二苯烷基胺母核 <a class="header-anchor" href="#_14-美沙酮-methadone-开链二苯烷基胺母核" aria-label="Permalink to “14. 美沙酮（Methadone）开链二苯烷基胺母核”">​</a> <a class="header-anchor" href="#_14-美沙酮-methadone-开链二苯烷基胺母核" aria-label="Permalink to “14. 美沙酮（Methadone）开链二苯烷基胺母核”">​</a></h3><p><img src="/images/controlled-substances/14-methadone-skeleton.png" alt="美沙酮开链母核骨架" width="1268" height="1656"></p><ul><li><strong>结构解析</strong>：展示 3,3-二苯基己酸酰胺与庚酮骨架在空间折叠中通过叔氮原子与羰基形成的准杂环伪环状空间稳定构型。</li></ul><h3 id="_15-美沙酮旋光异构体与乙酰美沙醇-laam" tabindex="-1">15. 美沙酮旋光异构体与乙酰美沙醇（LAAM） <a class="header-anchor" href="#_15-美沙酮旋光异构体与乙酰美沙醇-laam" aria-label="Permalink to “15. 美沙酮旋光异构体与乙酰美沙醇（LAAM）”">​</a> <a class="header-anchor" href="#_15-美沙酮旋光异构体与乙酰美沙醇-laam" aria-label="Permalink to “15. 美沙酮旋光异构体与乙酰美沙醇（LAAM）”">​</a></h3><p><img src="/images/controlled-substances/15-methadone-optical-isomers.png" alt="美沙酮光学异构体与 LAAM" width="1234" height="1675"></p><ul><li><strong>涵盖分子</strong>：(R)-左旋美沙酮（活性中心）、外消旋美沙酮、左旋乙酰美沙醇（LAAM/Levacetylmethadol，长效阿片替代药物）。</li></ul><h3 id="_16-美沙酮同系物与右丙氧芬" tabindex="-1">16. 美沙酮同系物与右丙氧芬 <a class="header-anchor" href="#_16-美沙酮同系物与右丙氧芬" aria-label="Permalink to “16. 美沙酮同系物与右丙氧芬”">​</a> <a class="header-anchor" href="#_16-美沙酮同系物与右丙氧芬" aria-label="Permalink to “16. 美沙酮同系物与右丙氧芬”">​</a></h3><p><img src="/images/controlled-substances/16-methadone-analogues-propoxyphene.png" alt="美沙酮类似物与丙氧芬" width="1268" height="1656"></p><ul><li><strong>涵盖分子</strong>：右丙氧芬（Dextropropoxyphene / Darvon，附表四镇痛药）、左旋丙氧芬（Levopropoxyphene，镇咳药，法条特别豁免）。</li></ul><h3 id="_17-1-4-苯二氮䓬类-benzodiazepines-母核骨架" tabindex="-1">17. 1,4-苯二氮䓬类（Benzodiazepines）母核骨架 <a class="header-anchor" href="#_17-1-4-苯二氮䓬类-benzodiazepines-母核骨架" aria-label="Permalink to “17. 1,4-苯二氮䓬类（Benzodiazepines）母核骨架”">​</a> <a class="header-anchor" href="#_17-1-4-苯二氮䓬类-benzodiazepines-母核骨架" aria-label="Permalink to “17. 1,4-苯二氮䓬类（Benzodiazepines）母核骨架”">​</a></h3><p><img src="/images/controlled-substances/17-benzodiazepine-skeleton.png" alt="1,4-苯二氮䓬基础母核骨架" width="1231" height="1677"></p><ul><li><strong>结构解析</strong>：经典的 5-苯基-1,3-二氢-2H-1,4-苯二氮䓬-2-酮结构，标定 A 环（7 位电负性取代基卤素/硝基）、B 环（4,5 位亚胺双键与 3 位羟基）、C 环（2&#39; 位卤素取代）。</li></ul><h3 id="_18-常见列管苯二氮䓬类药物对照矩阵" tabindex="-1">18. 常见列管苯二氮䓬类药物对照矩阵 <a class="header-anchor" href="#_18-常见列管苯二氮䓬类药物对照矩阵" aria-label="Permalink to “18. 常见列管苯二氮䓬类药物对照矩阵”">​</a> <a class="header-anchor" href="#_18-常见列管苯二氮䓬类药物对照矩阵" aria-label="Permalink to “18. 常见列管苯二氮䓬类药物对照矩阵”">​</a></h3><p><img src="/images/controlled-substances/18-benzodiazepines-table.png" alt="苯二氮䓬类核心取代基图谱" width="1274" height="1648"></p><ul><li><strong>涵盖分子</strong>：地西泮（Diazepam/安定）、氯氮䓬（Chlordiazepoxide/利眠宁）、氟西泮（Flurazepam）、硝西泮（Nitrazepam）、氯硝西泮（Clonazepam）、奥沙西泮（Oxazepam）、劳拉西泮（Lorazepam）、替马西泮（Temazepam）。</li></ul><h3 id="_19-苯二氮䓬苯环异构体与变体" tabindex="-1">19. 苯二氮䓬苯环异构体与变体 <a class="header-anchor" href="#_19-苯二氮䓬苯环异构体与变体" aria-label="Permalink to “19. 苯二氮䓬苯环异构体与变体”">​</a> <a class="header-anchor" href="#_19-苯二氮䓬苯环异构体与变体" aria-label="Permalink to “19. 苯二氮䓬苯环异构体与变体”">​</a></h3><p><img src="/images/controlled-substances/19-benzo-analogues-of-benzodiazepines.png" alt="苯二氮䓬类苯环异构体" width="1231" height="1677"></p><ul><li><strong>涵盖分子</strong>：氯巴占（Clobazam，1,5-苯二氮䓬骨架变体）、普拉西泮（Prazepam，环甲基侧链修饰）。</li></ul><h3 id="_20-稠环三唑并与咪唑并苯二氮䓬" tabindex="-1">20. 稠环三唑并与咪唑并苯二氮䓬 <a class="header-anchor" href="#_20-稠环三唑并与咪唑并苯二氮䓬" aria-label="Permalink to “20. 稠环三唑并与咪唑并苯二氮䓬”">​</a> <a class="header-anchor" href="#_20-稠环三唑并与咪唑并苯二氮䓬" aria-label="Permalink to “20. 稠环三唑并与咪唑并苯二氮䓬”">​</a></h3><p><img src="/images/controlled-substances/20-triazolo-imidazo-benzodiazepines.png" alt="三唑并与咪唑并苯二氮䓬稠环" width="1276" height="1641"></p><ul><li><strong>涵盖分子</strong>：阿普唑仑（Alprazolam / Xanax）、三唑仑（Triazolam / 海乐神）、咪达唑仑（Midazolam / 咪哒唑仑）、艾司唑仑（Estazolam）。</li></ul><h3 id="_21-取代苯乙胺与安非他命类-amphetamines" tabindex="-1">21. 取代苯乙胺与安非他命类（Amphetamines） <a class="header-anchor" href="#_21-取代苯乙胺与安非他命类-amphetamines" aria-label="Permalink to “21. 取代苯乙胺与安非他命类（Amphetamines）”">​</a> <a class="header-anchor" href="#_21-取代苯乙胺与安非他命类-amphetamines" aria-label="Permalink to “21. 取代苯乙胺与安非他命类（Amphetamines）”">​</a></h3><p><img src="/images/controlled-substances/21-substituted-amphetamines.png" alt="取代苯乙胺类与安非他命谱系" width="1229" height="1675"></p><ul><li><strong>涵盖分子</strong>：苯丙胺（Amphetamine）、甲基苯丙胺（Methamphetamine）、MDMA（3,4-亚甲二氧基甲基苯丙胺）、MDA、MDE（Eve）、DOM（STP/2,5-二甲氧基-4-甲基苯丙胺）、DOB、PMA。</li></ul><h3 id="_22-特殊苯乙胺类似物与杂环兴奋剂" tabindex="-1">22. 特殊苯乙胺类似物与杂环兴奋剂 <a class="header-anchor" href="#_22-特殊苯乙胺类似物与杂环兴奋剂" aria-label="Permalink to “22. 特殊苯乙胺类似物与杂环兴奋剂”">​</a> <a class="header-anchor" href="#_22-特殊苯乙胺类似物与杂环兴奋剂" aria-label="Permalink to “22. 特殊苯乙胺类似物与杂环兴奋剂”">​</a></h3><p><img src="/images/controlled-substances/22-unusual-amphetamine-relatives.png" alt="非典型苯丙胺同族衍生物" width="1270" height="1648"></p><ul><li><strong>涵盖分子</strong>：哌醋甲酯（Methylphenidate / 利他林）、苯甲曲秦（Phendimetrazine）、苄非他明（Benzphetamine）、芬氟拉明（Fenfluramine）。</li></ul><h3 id="_23-色胺与吲哚类致幻剂-tryptamines-indoles" tabindex="-1">23. 色胺与吲哚类致幻剂（Tryptamines &amp; Indoles） <a class="header-anchor" href="#_23-色胺与吲哚类致幻剂-tryptamines-indoles" aria-label="Permalink to “23. 色胺与吲哚类致幻剂（Tryptamines &amp; Indoles）”">​</a> <a class="header-anchor" href="#_23-色胺与吲哚类致幻剂-tryptamines-indoles" aria-label="Permalink to “23. 色胺与吲哚类致幻剂（Tryptamines &amp; Indoles）”">​</a></h3><p><img src="/images/controlled-substances/23-indoles-and-tryptamines.png" alt="吲哚与色胺类致幻剂图谱" width="1231" height="1675"></p><ul><li><strong>涵盖分子</strong>：LSD（麦角酸二乙酰胺）、Psilocybin（裸盖菇素）、Psilocin（脱磷酸裸盖菇素）、DMT（N,N-二甲基色胺）、DET（二乙基色胺）、5-MeO-DMT、蟾毒色胺（Bufotenine）。</li></ul><h3 id="_24-巴比妥酸-5-5-双取代衍生物-第一部分" tabindex="-1">24. 巴比妥酸 5,5-双取代衍生物（第一部分） <a class="header-anchor" href="#_24-巴比妥酸-5-5-双取代衍生物-第一部分" aria-label="Permalink to “24. 巴比妥酸 5,5-双取代衍生物（第一部分）”">​</a> <a class="header-anchor" href="#_24-巴比妥酸-5-5-双取代衍生物-第一部分" aria-label="Permalink to “24. 巴比妥酸 5,5-双取代衍生物（第一部分）”">​</a></h3><p><img src="/images/controlled-substances/24-barbituric-acid-derivatives-1.png" alt="巴比妥酸衍生物图谱 1" width="1270" height="1647"></p><ul><li><strong>涵盖分子</strong>：巴比妥（Barbital / 佛罗拿）、苯巴比妥（Phenobarbital / 鲁米那）、异戊巴比妥（Amobarbital）。</li></ul><h3 id="_25-巴比妥酸-5-5-双取代衍生物-第二部分" tabindex="-1">25. 巴比妥酸 5,5-双取代衍生物（第二部分） <a class="header-anchor" href="#_25-巴比妥酸-5-5-双取代衍生物-第二部分" aria-label="Permalink to “25. 巴比妥酸 5,5-双取代衍生物（第二部分）”">​</a> <a class="header-anchor" href="#_25-巴比妥酸-5-5-双取代衍生物-第二部分" aria-label="Permalink to “25. 巴比妥酸 5,5-双取代衍生物（第二部分）”">​</a></h3><p><img src="/images/controlled-substances/25-barbituric-acid-derivatives-2.png" alt="巴比妥酸衍生物图谱 2" width="1231" height="1675"></p><ul><li><strong>涵盖分子</strong>：司可巴比妥（Secobarbital / 速可眠）、戊巴比妥（Pentobarbital）、丁巴比妥（Butabarbital）、阿罗巴比妥（Allobarbital）。</li></ul><h3 id="_26-n-甲基与硫代巴比妥类" tabindex="-1">26. N-甲基与硫代巴比妥类 <a class="header-anchor" href="#_26-n-甲基与硫代巴比妥类" aria-label="Permalink to “26. N-甲基与硫代巴比妥类”">​</a> <a class="header-anchor" href="#_26-n-甲基与硫代巴比妥类" aria-label="Permalink to “26. N-甲基与硫代巴比妥类”">​</a></h3><p><img src="/images/controlled-substances/26-methyl-barbiturates.png" alt="N-甲基与硫代巴比妥衍生物" width="1270" height="1647"></p><ul><li><strong>涵盖分子</strong>：己巴比妥（Hexobarbital）、甲苯巴比妥（Mephobarbital）、硫喷妥钠（Thiopental，超短效静脉麻醉剂）。</li></ul><h3 id="_27-苯环己哌啶-pcp-及其芳基环己胺类似物" tabindex="-1">27. 苯环己哌啶（PCP）及其芳基环己胺类似物 <a class="header-anchor" href="#_27-苯环己哌啶-pcp-及其芳基环己胺类似物" aria-label="Permalink to “27. 苯环己哌啶（PCP）及其芳基环己胺类似物”">​</a> <a class="header-anchor" href="#_27-苯环己哌啶-pcp-及其芳基环己胺类似物" aria-label="Permalink to “27. 苯环己哌啶（PCP）及其芳基环己胺类似物”">​</a></h3><p><img src="/images/controlled-substances/27-phencyclidine-pcp-analogues.png" alt="苯环己哌啶类似物图谱" width="1236" height="1670"></p><ul><li><strong>涵盖分子</strong>：<strong>苯环利定（PCP / 天使粉）</strong>、PCE（N-乙基-1-苯基环己胺）、PHP / PCPY（1-(1-苯基环己基)吡咯烷）、TCP（1-[1-(2-噻吩基)环己基]哌啶）。</li></ul><h3 id="_28-同化雄激素类固醇-睾酮骨架变体" tabindex="-1">28. 同化雄激素类固醇（睾酮骨架变体） <a class="header-anchor" href="#_28-同化雄激素类固醇-睾酮骨架变体" aria-label="Permalink to “28. 同化雄激素类固醇（睾酮骨架变体）”">​</a> <a class="header-anchor" href="#_28-同化雄激素类固醇-睾酮骨架变体" aria-label="Permalink to “28. 同化雄激素类固醇（睾酮骨架变体）”">​</a></h3><p><img src="/images/controlled-substances/28-anabolic-steroids-testosterone.png" alt="同化雄激素类固醇图谱 1" width="1263" height="1652"></p><ul><li><strong>涵盖分子</strong>：甲基睾酮（Methyltestosterone）、甲睾酮、去氢甲睾酮（Methandrostenolone / 大力补 Dianabol）、氟羟甲基睾酮（Fluoxymesterone）。</li></ul><h3 id="_29-19-去甲睾酮衍生物-诺龙系列" tabindex="-1">29. 19-去甲睾酮衍生物（诺龙系列） <a class="header-anchor" href="#_29-19-去甲睾酮衍生物-诺龙系列" aria-label="Permalink to “29. 19-去甲睾酮衍生物（诺龙系列）”">​</a> <a class="header-anchor" href="#_29-19-去甲睾酮衍生物-诺龙系列" aria-label="Permalink to “29. 19-去甲睾酮衍生物（诺龙系列）”">​</a></h3><p><img src="/images/controlled-substances/29-anabolic-steroids-nandrolone.png" alt="同化雄激素类固醇图谱 2" width="1231" height="1675"></p><ul><li><strong>涵盖分子</strong>：苯丙酸诺龙（Nandrolone phenpropionate）、癸酸诺龙（Nandrolone decanoate）、康力龙（Stanozolol / 司坦唑醇）、氧雄龙（Oxandrolone）。</li></ul><h3 id="_30-砜类与单胺型老式镇静安眠药" tabindex="-1">30. 砜类与单胺型老式镇静安眠药 <a class="header-anchor" href="#_30-砜类与单胺型老式镇静安眠药" aria-label="Permalink to “30. 砜类与单胺型老式镇静安眠药”">​</a> <a class="header-anchor" href="#_30-砜类与单胺型老式镇静安眠药" aria-label="Permalink to “30. 砜类与单胺型老式镇静安眠药”">​</a></h3><p><img src="/images/controlled-substances/30-sulfones-and-sedatives.png" alt="砜类与非巴比妥类镇静催眠药" width="1272" height="1640"></p><ul><li><strong>涵盖分子</strong>：磺甲烷（Sulfonal / Sulfonmethane）、磺乙烷（Sulfondiethylmethane）、水合氯醛（Chloral hydrate）、格鲁米特（Glutethimide / 导眠能）、甲乙哌酮（Methyprylon）。</li></ul><h3 id="_31-大麻素类活性成分与同系物" tabindex="-1">31. 大麻素类活性成分与同系物 <a class="header-anchor" href="#_31-大麻素类活性成分与同系物" aria-label="Permalink to “31. 大麻素类活性成分与同系物”">​</a> <a class="header-anchor" href="#_31-大麻素类活性成分与同系物" aria-label="Permalink to “31. 大麻素类活性成分与同系物”">​</a></h3><p><img src="/images/controlled-substances/31-cannabis-components.png" alt="大麻天然与合成活性分子图谱" width="1236" height="1666"></p><ul><li><strong>涵盖分子</strong>：Δ9-四氢大麻酚（Δ9-THC）、Δ8-THC、大麻酚（CBN）、大麻二酚（CBD）、人工合成大麻素派拉六基（Parahexyl / 双甲基己基四氢大麻酚）。</li></ul><h3 id="_32-苯并咪唑类强效阿片镇痛剂" tabindex="-1">32. 苯并咪唑类强效阿片镇痛剂 <a class="header-anchor" href="#_32-苯并咪唑类强效阿片镇痛剂" aria-label="Permalink to “32. 苯并咪唑类强效阿片镇痛剂”">​</a> <a class="header-anchor" href="#_32-苯并咪唑类强效阿片镇痛剂" aria-label="Permalink to “32. 苯并咪唑类强效阿片镇痛剂”">​</a></h3><p><img src="/images/controlled-substances/32-benzimidazole-analgesics.png" alt="苯并咪唑类强效阿片镇痛衍生物" width="1272" height="1640"></p><ul><li><strong>涵盖分子</strong>：依他氮烯（Etonitazene）、氯硝氮烯（Clonitazene）。（其阿片受体亲和力与镇痛活性为吗啡的数十至数百倍）。</li></ul><h3 id="_33-孤品与特殊独立结构化学实体" tabindex="-1">33. 孤品与特殊独立结构化学实体 <a class="header-anchor" href="#_33-孤品与特殊独立结构化学实体" aria-label="Permalink to “33. 孤品与特殊独立结构化学实体”">​</a> <a class="header-anchor" href="#_33-孤品与特殊独立结构化学实体" aria-label="Permalink to “33. 孤品与特殊独立结构化学实体”">​</a></h3><p><img src="/images/controlled-substances/33-one-of-a-kind-compounds.png" alt="孤立骨架受管制化学实体图谱" width="1229" height="1675"></p><ul><li><strong>涵盖分子</strong>：甲喹酮（Methaqualone / 安眠酮）、甲基苯乙哌啶（Phenmetrazine / 阿西特朗）、氨苯苄酯（Pemoline / 匹莫林）、二甲氧基溴苯乙胺（DOB）、二乙基丙酮（Diethylpropion）。</li></ul>`,117),n(m),n(h)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};